"use client";

import { useEffect, useRef } from "react";
import { geoOrthographic, geoPath, geoGraticule10, geoDistance } from "d3-geo";
import type { GeoPermissibleObjects } from "d3-geo";
import { feature } from "topojson-client";
import type { Topology, GeometryCollection } from "topojson-specification";
import type { FeatureCollection, Geometry } from "geojson";

/**
 * Live activity globe. A real orthographic-projection Earth rendered with
 * Canvas 2D: Natural Earth country landmasses + outlines (public-domain
 * `world-atlas` topojson, shipped as /countries-110m.json), a subtle graticule,
 * an ocean-tinted sphere with a soft outer glow, and slow auto-rotation.
 *
 * Recent visitor lat/lng are drawn as pulsing markers (a core dot with an
 * expanding/fading ring), colored by source per the legend (marketing = green,
 * portal = violet). Occlusion is handled by the orthographic hemisphere: land
 * is clipped by d3's geoOrthographic (clipAngle 90), and each marker's angular
 * distance to the projection centre decides whether it is hidden (back) or how
 * dim it is (near the limb).
 *
 * Honors `prefers-reduced-motion` by holding a near-static frame.
 */

export type GlobePoint = {
  lat: number;
  lng: number;
  city: string | null;
  country: string | null;
  kind: string;
};

type World = { land: FeatureCollection<Geometry>; borders: FeatureCollection<Geometry> };

// World geometry: fetched once and cached across mounts.
let worldCache: World | null = null;
let worldPromise: Promise<World | null> | null = null;

async function loadWorld(): Promise<World | null> {
  if (worldCache) return worldCache;
  if (!worldPromise) {
    worldPromise = fetch("/countries-110m.json")
      .then((r) => r.json())
      .then((topo: Topology) => {
        const land = feature(
          topo,
          topo.objects.land as GeometryCollection,
        ) as FeatureCollection<Geometry>;
        const borders = feature(
          topo,
          topo.objects.countries as GeometryCollection,
        ) as FeatureCollection<Geometry>;
        worldCache = { land, borders };
        return worldCache;
      })
      .catch(() => null);
  }
  return worldPromise;
}

export default function VisitorGlobe({ points }: { points: GlobePoint[] }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced =
      typeof window !== "undefined" &&
      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

    let raf = 0;
    let disposed = false;
    let world: World | null = worldCache;

    // Logical drawing size; backing store scaled for crisp HiDPI.
    const SIZE = 460;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = SIZE * dpr;
    canvas.height = SIZE * dpr;
    ctx.scale(dpr, dpr);

    const cx = SIZE / 2;
    const cy = SIZE / 2;
    const R = SIZE / 2 - 24;
    const TILT = -16; // centre the view a touch north of the equator

    // Orthographic projection fitted to the sphere disc. clipAngle 90 (the d3
    // default) hides back-hemisphere land automatically.
    const projection = geoOrthographic().scale(R).translate([cx, cy]).clipAngle(90);
    const path = geoPath(projection, ctx);
    const graticule = geoGraticule10() as unknown as GeoPermissibleObjects;

    // Each visit as a [lng, lat] pair (d3 order) with a random pulse phase.
    const markers = points.map((p) => ({
      coord: [p.lng, p.lat] as [number, number],
      seed: Math.random() * Math.PI * 2,
      portal: p.kind === "portal",
    }));

    let last = 0;
    let lambda = 0; // spin angle around the polar axis
    let acc = 0;
    const FRAME_MS = 1000 / 30; // throttle draws to ~30fps to keep CPU reasonable

    function render(t: number) {
      ctx!.clearRect(0, 0, SIZE, SIZE);

      // Soft outer glow behind the sphere.
      const glow = ctx!.createRadialGradient(cx, cy, R * 0.9, cx, cy, R * 1.28);
      glow.addColorStop(0, "rgba(138,112,251,0.18)");
      glow.addColorStop(1, "rgba(138,112,251,0)");
      ctx!.beginPath();
      ctx!.arc(cx, cy, R * 1.28, 0, Math.PI * 2);
      ctx!.fillStyle = glow;
      ctx!.fill();

      // Ocean sphere with a radial shade for volume.
      const ocean = ctx!.createRadialGradient(cx - R * 0.35, cy - R * 0.4, R * 0.15, cx, cy, R);
      ocean.addColorStop(0, "rgba(59,130,246,0.20)");
      ocean.addColorStop(0.55, "rgba(40,30,90,0.42)");
      ocean.addColorStop(1, "rgba(10,8,25,0.72)");
      ctx!.beginPath();
      ctx!.arc(cx, cy, R, 0, Math.PI * 2);
      ctx!.fillStyle = ocean;
      ctx!.fill();

      // Graticule on the visible hemisphere.
      ctx!.beginPath();
      path(graticule);
      ctx!.lineWidth = 0.6;
      ctx!.strokeStyle = "rgba(255,255,255,0.055)";
      ctx!.stroke();

      if (world) {
        // Country landmasses — filled violet-slate.
        ctx!.beginPath();
        path(world.land as unknown as GeoPermissibleObjects);
        ctx!.fillStyle = "rgba(139,120,225,0.20)";
        ctx!.fill();

        // Country outlines.
        ctx!.beginPath();
        path(world.borders as unknown as GeoPermissibleObjects);
        ctx!.lineWidth = 0.5;
        ctx!.strokeStyle = "rgba(170,150,255,0.30)";
        ctx!.stroke();
      }

      // Rim light on the sphere edge.
      ctx!.beginPath();
      ctx!.arc(cx, cy, R, 0, Math.PI * 2);
      ctx!.lineWidth = 1.2;
      ctx!.strokeStyle = "rgba(138,112,251,0.5)";
      ctx!.stroke();

      // Visit markers — only the front hemisphere, with a time-based pulse.
      const rot = projection.rotate();
      const centreLL: [number, number] = [-rot[0], -rot[1]];
      for (const m of markers) {
        const dist = geoDistance(m.coord, centreLL);
        if (dist >= Math.PI / 2) continue; // behind the globe
        const xy = projection(m.coord);
        if (!xy) continue;
        const depth = Math.cos(dist); // 1 at centre, 0 at the limb
        const edgeFade = 0.35 + 0.65 * depth;
        const core = m.portal ? "138,112,251" : "52,211,153"; // violet vs emerald
        const pulse = reduced ? 0.6 : 0.5 + 0.5 * Math.sin(t * 0.004 + m.seed);

        // expanding/fading ring
        ctx!.beginPath();
        ctx!.arc(xy[0], xy[1], 3 + pulse * 8, 0, Math.PI * 2);
        ctx!.lineWidth = 1.2;
        ctx!.strokeStyle = `rgba(${core},${(0.35 * (1 - pulse) + 0.05) * edgeFade})`;
        ctx!.stroke();
        // glow
        ctx!.beginPath();
        ctx!.arc(xy[0], xy[1], 5 + pulse * 4, 0, Math.PI * 2);
        ctx!.fillStyle = `rgba(${core},${0.12 * edgeFade})`;
        ctx!.fill();
        // core dot
        ctx!.beginPath();
        ctx!.arc(xy[0], xy[1], 2.2, 0, Math.PI * 2);
        ctx!.fillStyle = `rgba(${core},${(0.8 + 0.2 * pulse) * edgeFade})`;
        ctx!.fill();
      }
    }

    function frame(t: number) {
      if (disposed) return;
      if (!last) last = t;
      const dt = t - last;
      last = t;
      acc += dt;

      lambda += 0.006 * dt; // ~6°/s — a slow, calm rotation
      if (lambda >= 360) lambda -= 360;
      projection.rotate([lambda, TILT]);

      if (acc >= FRAME_MS) {
        acc = 0;
        render(t);
      }
      raf = requestAnimationFrame(frame);
    }

    // Load geometry, then start. If already cached, `world` is set above and the
    // first animated frame paints land immediately.
    loadWorld().then((w) => {
      if (disposed) return;
      world = w;
      if (reduced) {
        projection.rotate([-10, TILT]);
        render(0);
      }
    });

    if (reduced) {
      projection.rotate([-10, TILT]);
      render(0);
    } else {
      raf = requestAnimationFrame(frame);
    }

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
    };
  }, [points]);

  return (
    <div className="card flex flex-col items-center justify-center overflow-hidden p-4">
      <div className="mb-2 flex w-full items-center justify-between">
        <h2 className="font-semibold">Live activity globe</h2>
        <span className="text-xs text-slate-500">{points.length} recent</span>
      </div>
      <div className="relative">
        <canvas
          ref={canvasRef}
          style={{ width: 460, height: 460, maxWidth: "100%" }}
          aria-label="Rotating globe plotting recent visitor locations"
          role="img"
        />
      </div>
      <div className="mt-2 flex items-center gap-4 text-xs text-slate-400">
        <span className="inline-flex items-center gap-1.5">
          <span className="h-2 w-2 rounded-full" style={{ background: "#34d399" }} /> marketing
        </span>
        <span className="inline-flex items-center gap-1.5">
          <span className="h-2 w-2 rounded-full" style={{ background: "#8a70fb" }} /> portal
        </span>
      </div>
      {points.length === 0 && (
        <p className="mt-3 max-w-xs text-center text-xs text-slate-500">
          No geocoded visits yet — dots appear here as the worker resolves visitor locations.
        </p>
      )}
    </div>
  );
}
